// stream Claude Code is not yet reading. (On stdio that would be a malformed
// frame, not merely a lost message.)
if (CHANNEL_ENABLED) {
    scheduleLoop(CWD, POLL_MS, sendBatch, (err) => {
        process.stderr.write(`agy-watch: ${String(err)}\n`);
    });
}